CREATE TABLE IF NOT EXISTS shop_chat(id BIGINT PRIMARY KEY AUTO_INCREMENT,member_id BIGINT NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'open',assigned_to VARCHAR(64) NULL,member_read_id BIGINT NOT NULL DEFAULT 0,staff_read_id BIGINT NOT NULL DEFAULT 0,protected BOOLEAN NOT NULL DEFAULT FALSE,last_message_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shop_chat_image(id BIGINT PRIMARY KEY AUTO_INCREMENT,chat_id BIGINT NOT NULL,path VARCHAR(100) NOT NULL UNIQUE,uploader VARCHAR(80) NOT NULL,message_id BIGINT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shop_chat_message(id BIGINT PRIMARY KEY AUTO_INCREMENT,chat_id BIGINT NOT NULL,sender VARCHAR(20) NOT NULL,sender_id VARCHAR(80) NOT NULL,body VARCHAR(2000) NOT NULL,image_id BIGINT NULL,order_id BIGINT NULL,request_key VARCHAR(80) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY chat_send(chat_id,sender_id,request_key),INDEX chat_messages(chat_id,id));
INSERT IGNORE INTO shop_config(config_key,content) VALUES('support','{"startHour":9,"endHour":18,"weekdaysOnly":true,"idleDays":7,"retentionDays":180,"offlineText":"客服当前不在线，您可以先留言，上班后会尽快回复。"}');
CREATE TABLE IF NOT EXISTS shop_chat_file_gc(path VARCHAR(100) PRIMARY KEY,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
